local DoorColor         = Color3.fromRGB(120, 255, 120)
local ItemsColor        = Color3.fromRGB(0, 50, 180)
local HidingPlaceColor  = Color3.fromRGB(255, 255, 255)
local LeverColor        = Color3.fromRGB(150, 150, 150)
